template.solver:
def solve(u1, t1, u2, b):
    # Закон теплообмена: поток тепла от батареи к комнате пропорционален разности температур
    # (b - t) = k * (t - (-u)), где k находится из первого состояния
    k = (b - t1) / (t1 + u1)
    # Во втором состоянии: b - t = k * (t + u2)
    return (b - k * u2) / (1 + k)
